CREATE FUNCTION app_enquiry_retention_targets(p_now timestamptz)
  RETURNS TABLE (workspace_id uuid)
  LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_temp
  AS $$
    SELECT DISTINCT e.workspace_id FROM enquiry e
    WHERE e.status = 'closed' AND e.closed_at <= p_now - interval '1 month'
    ORDER BY e.workspace_id
    LIMIT 1000
  $$;--> statement-breakpoint
REVOKE ALL ON FUNCTION app_enquiry_retention_targets(timestamptz) FROM PUBLIC;--> statement-breakpoint
GRANT EXECUTE ON FUNCTION app_enquiry_retention_targets(timestamptz) TO causedeck_app;
